import { EXTENDED_UNIVERSITIES, EXTENDED_PROGRAMS, EXTENDED_CONTACTS } from "../core/globalCatalog.ts";
const q = (v: unknown) => (v === null || v === undefined || v === "" ? "NULL" : typeof v === "number" ? String(v) : `'${String(v).replace(/'/g, "''")}'`);
const out: string[] = [
  "-- Cloudflare D1 Migration 0006: load the curated catalogue from core/globalCatalog.ts",
  "-- Generated by scripts/gen-catalog-seed.ts. Records are hand-curated, not crawled: last_verified stays NULL until the crawler confirms them.",
];
for (const u of EXTENDED_UNIVERSITIES) {
  out.push(`INSERT OR REPLACE INTO universities (id, name, country, country_code, city, website, domain, ranking, languages, tuition_min, tuition_max, currency, intake_months, source_url, source_type, last_verified) VALUES (${[u.id, u.name, u.country, u.country_code, u.city, u.website, u.domain, u.ranking, u.languages, u.tuition_min, u.tuition_max, u.currency, u.intake_months, u.source_url, u.source_type].map(q).join(", ")}, NULL);`);
}
for (const p of EXTENDED_PROGRAMS) {
  out.push(`INSERT OR REPLACE INTO programs (id, university_id, name, level, original_degree, department, language, duration_months, tuition, deadline, requirements, program_url, admissions_url, subject_category, application_mode, source_url, source_type, last_verified) VALUES (${[p.id, p.university_id, p.name, p.level, p.original_degree || p.level, p.department, p.language, p.duration_months, p.tuition, p.deadline, p.requirements, p.program_url, p.admissions_url, p.subject_category, p.application_mode, p.source_url, p.source_type].map(q).join(", ")}, NULL);`);
}
for (const c of EXTENDED_CONTACTS) {
  out.push(`INSERT OR REPLACE INTO contacts (id, university_id, department, name, role, email, email_type, phone, source_url, fetched_at) VALUES (${[c.id, c.university_id, c.department, c.name, c.role, c.email, c.email_type, c.phone, c.source_url].map(q).join(", ")}, NULL);`);
}
process.stdout.write(out.join("\n") + "\n");
